// GENERATED by `go run ./cmd/sdkcontract` in the api repo from internal/sdkcontract. Do not edit; regenerate and copy.
@file:Suppress("unused")

package io.unilitix.sdk.contract

import java.io.File

/**
 * Behaviour fixture loader (README.md next to the fixtures is the runner
 * contract). Reads api/sdk/behaviour/ copied into the repo. JVM only, no
 * dependencies: org.json is a stub in local unit tests, so a small JSON
 * reader is included. Objects are LinkedHashMap (file order), numbers Long
 * or Double.
 */
object BehaviourFixtures {
    const val CONTRACT_VERSION: String = "1.4.0"
    val steps: List<String> = listOf("init", "track", "screen", "identify", "reset", "setConsent", "advanceTime", "setNetwork", "background", "foreground", "flush", "recordError", "crashNextLaunch", "restart", "serverResponds", "repeat", "expectRequests", "expectEvents", "expectState")
    val stateKeys: List<String> = listOf("anonymousId", "consent", "queueLength", "replaySampled", "screen", "sessionId", "uploadsPaused", "userId")

    data class Step(val action: String, val args: Any?)

    data class Case(
        val id: String,
        val description: String,
        val area: String,
        /** null: every SDK. */
        val platforms: List<String>?,
        /** Harness config merged with the case's overrides, by canonical option key. */
        val config: Map<String, Any?>,
        val clock: String,
        /** {type, generation?, online} */
        val network: Map<String, Any?>,
        val randomRolls: List<Double>,
        val steps: List<Step>,
    )

    data class Fixtures(val harness: Map<String, Any?>, val cases: List<Case>)

    @Suppress("UNCHECKED_CAST")
    fun load(dir: File, platform: String = "android"): Fixtures {
        fun read(name: String) = Json.parse(File(dir, name).readText()) as Map<String, Any?>
        val index = read("index.json")
        check(index["contractVersion"] == CONTRACT_VERSION) {
            "fixtures are contract ${index["contractVersion"]}, loader $CONTRACT_VERSION"
        }
        val harness = index["harness"] as Map<String, Any?>
        val hDevice = harness["device"] as Map<String, Any?>
        val cases = mutableListOf<Case>()
        for (f in index["files"] as List<String>) {
            val file = read(f)
            for (c in file["cases"] as List<Map<String, Any?>>) {
                val plats = c["platforms"] as List<String>?
                if (plats != null && platform !in plats) continue
                val device = c["device"] as Map<String, Any?>? ?: emptyMap()
                cases += Case(
                    id = c["id"] as String,
                    description = c["description"] as String,
                    area = file["area"] as String,
                    platforms = plats,
                    config = (harness["config"] as Map<String, Any?>) + (c["config"] as Map<String, Any?>? ?: emptyMap()),
                    clock = (c["clock"] ?: harness["clock"]) as String,
                    network = (device["network"] ?: hDevice["network"]) as Map<String, Any?>,
                    randomRolls = ((device["randomRolls"] ?: hDevice["randomRolls"]) as List<Any?>).map { (it as Number).toDouble() },
                    steps = (c["steps"] as List<Map<String, Any?>>).map(::stepOf),
                )
            }
        }
        return Fixtures(harness, cases)
    }

    fun stepOf(raw: Map<String, Any?>): Step {
        require(raw.size == 1 && raw.keys.first() in steps) { "bad step $raw" }
        return Step(raw.keys.first(), raw.values.first())
    }

    /** Replaces "\${i}" in every string (repeat steps, \$each matchers). */
    fun substitute(v: Any?, i: Int): Any? = when (v) {
        is String -> v.replace("\${i}", i.toString())
        is List<*> -> v.map { substitute(it, i) }
        is Map<*, *> -> LinkedHashMap<String, Any?>().also { out -> v.forEach { (k, e) -> out[substitute(k, i) as String] = substitute(e, i) } }
        else -> v
    }

    /** The value an app passes for fixture input: \$number, \$repeat, \$keys, \$list decoded. */
    fun decodeInput(v: Any?): Any? {
        if (v is List<*>) return v.map(::decodeInput)
        if (v is Map<*, *>) {
            if (v.size == 1) {
                val g = v.values.first()
                when (v.keys.first()) {
                    "\$number" -> return if (g == "NaN") Double.NaN else if (g == "Infinity") Double.POSITIVE_INFINITY else Double.NEGATIVE_INFINITY
                    "\$repeat" -> { g as Map<*, *>; return (g["string"] as String).repeat((g["count"] as Number).toInt()) }
                    "\$keys" -> { g as Map<*, *>
                        val out = LinkedHashMap<String, Any?>()
                        for (i in 0 until (g["count"] as Number).toInt()) out["${g["prefix"]}$i"] = decodeInput(g["value"])
                        return out }
                    "\$list" -> { g as Map<*, *>; return List((g["count"] as Number).toInt()) { decodeInput(g["value"]) } }
                }
            }
            return LinkedHashMap<String, Any?>().also { out -> v.forEach { (k, e) -> out[k as String] = decodeInput(e) } }
        }
        return v
    }

    /** Minimal JSON reader (RFC 8259) for the fixtures. */
    object Json {
        fun parse(text: String): Any? = Reader(text).run { val v = value(); ws(); require(i == s.length) { "trailing data at $i" }; v }

        private class Reader(val s: String) {
            var i = 0
            fun ws() { while (i < s.length && s[i] in " \t\r\n") i++ }
            fun value(): Any? {
                ws()
                require(i < s.length) { "unexpected end" }
                return when (s[i]) {
                    '{' -> obj()
                    '[' -> arr()
                    '"' -> str()
                    't' -> lit("true", true)
                    'f' -> lit("false", false)
                    'n' -> lit("null", null)
                    else -> num()
                }
            }
            fun lit(w: String, v: Any?): Any? { require(s.startsWith(w, i)) { "bad literal at $i" }; i += w.length; return v }
            fun obj(): Map<String, Any?> {
                val out = LinkedHashMap<String, Any?>(); i++; ws()
                if (s[i] == '}') { i++; return out }
                while (true) {
                    ws(); val k = str(); ws(); require(s[i] == ':') { "expected : at $i" }; i++
                    out[k] = value(); ws()
                    if (s[i] == ',') { i++; continue }
                    require(s[i] == '}') { "expected } at $i" }; i++; return out
                }
            }
            fun arr(): List<Any?> {
                val out = ArrayList<Any?>(); i++; ws()
                if (s[i] == ']') { i++; return out }
                while (true) {
                    out += value(); ws()
                    if (s[i] == ',') { i++; continue }
                    require(s[i] == ']') { "expected ] at $i" }; i++; return out
                }
            }
            fun str(): String {
                require(s[i] == '"') { "expected string at $i" }; i++
                val b = StringBuilder()
                while (true) {
                    val c = s[i++]
                    when (c) {
                        '"' -> return b.toString()
                        '\\' -> when (val e = s[i++]) {
                            'n' -> b.append('\n')
                            't' -> b.append('\t')
                            'r' -> b.append('\r')
                            'b' -> b.append('\b')
                            'f' -> b.append('\u000c')
                            'u' -> { b.append(s.substring(i, i + 4).toInt(16).toChar()); i += 4 }
                            else -> b.append(e)
                        }
                        else -> b.append(c)
                    }
                }
            }
            fun num(): Any {
                val start = i
                while (i < s.length && s[i] in "+-0123456789.eE") i++
                val t = s.substring(start, i)
                return if (t.any { it in ".eE" }) t.toDouble() else t.toLong()
            }
        }
    }
}
